using HellParty.Rules;
using Mono.Cecil;
using Mono.Cecil.Cil;

// Standalone deterministic unit/assembly-contract runner. Does not load Unity
// or run the game, and fails the process when any assertion fails.
try
{
int passed = 0;
void Check(string name, bool condition)
{
    if (!condition) throw new InvalidOperationException("FAIL: " + name);
    Console.WriteLine("PASS: " + name);
    passed++;
}

Check("No crown at vanilla difficulty", !DifficultyRules.CrownVisible(0, 0));
foreach (int tier in new[] { 1, 2, 3, 4, 5 })
foreach (double elapsed in new[] { 0d, 0.999, 1, 4.999, 5, 5.999, 6, 9.999, 10, 1001 })
    Check($"Crown visibility tier {tier} at {elapsed}s", DifficultyRules.CrownVisible(tier, elapsed) ==
        (tier < 3 || elapsed % 5 < 1));

for (int completed = 0; completed < 12; completed++)
foreach (int players in new[] { 1, 6, 7, 12 })
{
    int amount = players >= 7 ? 2 : 1;
    int mediumBonus = completed < 4 || completed >= 9 ? amount : 0;
    int largeBonus = completed >= 4 ? amount : 0;
    Check($"Stage {completed + 1}, party {players}: native medium adjustment", MonsterSpawnBalanceRules.Count(2, completed, players, false, 5, true, true) == 2 + mediumBonus);
    Check($"Stage {completed + 1}, party {players}: native large adjustment", MonsterSpawnBalanceRules.Count(3, completed, players, true, 5, true, true) == 3 + largeBonus);
}
Check("A vanilla zero-medium opening gains its requested picks", MonsterSpawnBalanceRules.Count(0, 0, 7, false, 1, true, true) == 2);
Check("Vanilla baseline difficulty disables both count bonuses", MonsterSpawnBalanceRules.Count(2, 9, 7, false, 0, true, true) == 2 && MonsterSpawnBalanceRules.Count(3, 9, 7, true, 0, true, true) == 3);
Check("Guests cannot adjust native monster amounts", MonsterSpawnBalanceRules.Count(2, 9, 7, false, 5, false, true) == 2 && MonsterSpawnBalanceRules.Count(3, 9, 7, true, 5, false, true) == 3);
Check("Non-level scenes preserve both native counts", MonsterSpawnBalanceRules.Count(2, 9, 7, false, 5, true, false) == 2 && MonsterSpawnBalanceRules.Count(3, 9, 7, true, 5, true, false) == 3);
Check("Actual stage controls the band even under debug difficulty five", MonsterSpawnBalanceRules.Count(2, 4, 1, false, 5, true, true) == 2 && MonsterSpawnBalanceRules.Count(3, 4, 1, true, 5, true, true) == 4);
Check("Invalid progress, party sizes and native counts are preserved", MonsterSpawnBalanceRules.Count(2, -1, 7, false, 1, true, true) == 2 && MonsterSpawnBalanceRules.Count(2, 0, 0, false, 1, true, true) == 2 && MonsterSpawnBalanceRules.Count(-1, 9, 7, true, 5, true, true) == -1);
Check("Two extra picks cannot overflow the native count", MonsterSpawnBalanceRules.Count(int.MaxValue - 1, 9, 7, true, 5, true, true) == int.MaxValue);

Check("Native medium eligibility respects minimum and maximum progress", !MonsterSpawnBalanceRules.Eligible(true, 1, 2, 3, 5, 1) && MonsterSpawnBalanceRules.Eligible(true, 2, 2, 3, 5, 1) && MonsterSpawnBalanceRules.Eligible(true, 3, 2, 3, 5, 1) && !MonsterSpawnBalanceRules.Eligible(true, 4, 2, 3, 5, 1));
Check("A zero native maximum means no upper progress restriction", MonsterSpawnBalanceRules.Eligible(true, 99, 2, 0, 5, 1));
Check("Disabled native progress restrictions do not affect medium eligibility", MonsterSpawnBalanceRules.Eligible(false, 0, 10, 20, 1, 1));
Check("Native profile run-count locks remain enforced", !MonsterSpawnBalanceRules.Eligible(false, 0, 0, 0, 0, 1) && MonsterSpawnBalanceRules.Eligible(false, 0, 0, 0, 1, 1));

Check("Elsa assassination is unavailable below five", Enumerable.Range(0, 5).All(tier => !ElsaAssassinationClock.Eligible(tier, false)));
Check("Natural Elsa gains assassination at five", ElsaAssassinationClock.Eligible(5, false));
Check("All summoned Elsa origins are excluded", !ElsaAssassinationClock.Eligible(5, true));
Check("Elsa's target cannot count as its own companion", !ElsaAssassinationClock.CompanionNearby(true, true, 0));
Check("Dead or disabled players cannot protect a target", !ElsaAssassinationClock.CompanionNearby(false, false, 1));
Check("Another player at exactly twenty metres protects the target", ElsaAssassinationClock.CompanionNearby(true, false, 400));
Check("Companions outside twenty metres do not protect the target", !ElsaAssassinationClock.CompanionNearby(true, false, 400.001));
Check("Invalid companion distances do not count", !ElsaAssassinationClock.CompanionNearby(true, false, double.NaN) && !ElsaAssassinationClock.CompanionNearby(true, false, -1));
var assassination = new ElsaAssassinationClock();
Check("Elsa cannot assassinate from idle or targetless roaming", !assassination.Begin(0, false, false, 0));
Check("Elsa cannot assassinate a player with a nearby companion", !assassination.Begin(0, true, true, 1));
Check("Elsa waits until within five metres", !assassination.Begin(0, true, false, 25.001));
Check("Elsa rejects invalid assassination distances", !assassination.Begin(0, true, false, double.NaN) && !assassination.Begin(0, true, false, -1));
Check("An isolated player at exactly five metres permits the first immediate entry", assassination.Begin(100, true, false, 25) && assassination.Active);
Check("An active assassination cannot start twice", !assassination.Begin(101, true, false, 0));
Check("Companion arrival can immediately cancel during growth", assassination.End(101) && !assassination.Active);
Check("Repeated cancellation cannot modify the cooldown", !assassination.End(105));
Check("Reentry waits ten seconds from exit", !assassination.Begin(110.999, true, false, 1) && assassination.Begin(111, true, false, 1));
Check("Assassination has no ten-second lifetime", assassination.Active && !assassination.Begin(1000, true, false, 1));
assassination.End(1000);
Check("A long-lived mode also waits ten seconds after exit", !assassination.Begin(1000, true, false, 1) && !assassination.Begin(1009.999, true, false, 1) && assassination.Begin(1010, true, false, 1));
assassination.End(1011);
assassination.NewLife();
Check("A new native life clears mode and previous cooldown", !assassination.Active && assassination.Begin(0, true, false, 1));
Check("Separate Elsa instances do not share cooldowns", new ElsaAssassinationClock().Begin(0, true, false, 1));

var reuse = new SummonReuseClock();
Check("A never-parked summon cannot be reused", !reuse.Ready(100));
reuse.Observe(100, true);
Check("Hidden summons drain old messages before reuse", !reuse.Ready(101.999) && reuse.Ready(102));
reuse.Observe(101, true);
Check("Repeated hidden observations do not restart draining", reuse.Ready(102));
reuse.Reset();
Check("Reserving a pooled summon prevents a second reservation", !reuse.Ready(1000));
reuse.Observe(200, true);
reuse.Observe(201, false);
Check("An active or pending summon cannot be reused", !reuse.Ready(1000));
reuse.Observe(300, true);
Check("A later retirement starts a fresh drain period", !reuse.Ready(301.999) && reuse.Ready(302));
Check("New pool clocks do not inherit another instance's availability", !new SummonReuseClock().Ready(1000));
Check("Room budget permits exact capacity while preserving native headroom", RoomViewBudgetRules.Fits(999, 965, 2));
Check("Room budget refuses a multi-view prefab that would consume native headroom", !RoomViewBudgetRules.Fits(999, 966, 2));
Check("A full room refuses additional instantiation", !RoomViewBudgetRules.Fits(999, 999, 1));
Check("Other configured Photon limits use the same reserve rule", RoomViewBudgetRules.Fits(1999, 1965, 2));
Check("Invalid room counts and zero-view prefabs are rejected", !RoomViewBudgetRules.Fits(0, 0, 1) && !RoomViewBudgetRules.Fits(999, -1, 1) && !RoomViewBudgetRules.Fits(999, 0, 0));
Check("Budget arithmetic cannot wrap into allowing an overfull room", !RoomViewBudgetRules.Fits(int.MaxValue, int.MaxValue, int.MaxValue));

Check("Sticky Cleanup heads unlock at one", !CleanupStickyHeadClock<object>.Unlocked(0) && CleanupStickyHeadClock<object>.Unlocked(1));
Check("Sticky head range includes exactly one and a half metres", CleanupStickyHeadClock<object>.InRange(2.25) && CleanupStickyHeadClock<object>.InRange(2.249) && !CleanupStickyHeadClock<object>.InRange(2.251));
Check("Sticky heads reject invalid distances", !CleanupStickyHeadClock<object>.InRange(-1) && !CleanupStickyHeadClock<object>.InRange(double.NaN) && !CleanupStickyHeadClock<object>.InRange(double.PositiveInfinity));
var sticky = new CleanupStickyHeadClock<object>();
var carrierA = new object();
var carrierB = new object();
Check("The first head attachment is immediately ready", sticky.Attach(100, carrierA, false) && ReferenceEquals(sticky.Carrier, carrierA));
Check("A held head never attaches to a nearby player", !sticky.Attach(100, carrierB, true));
Check("Initial attachment does not start cooldown or delay the first transfer", sticky.Ready(100, false) && sticky.Attach(100, carrierB, false));
Check("Leaving the previous carrier starts transfer cooldown", !sticky.Attach(102.999, carrierA, false));
Check("A head can transfer exactly three seconds after the previous detachment", sticky.Attach(103, carrierA, false) && ReferenceEquals(sticky.Carrier, carrierA));
Check("Remaining on the same carrier never refreshes cooldown", !sticky.Attach(106, carrierA, false) && sticky.Attach(106, carrierB, false));
Check("Grab detaches a pinned head immediately", sticky.Detach(107) && sticky.Carrier == null);
Check("Grab detachment provides three seconds before sticking again", !sticky.Attach(109.999, carrierA, false) && sticky.Attach(110, carrierA, false));
Check("Reattachment does not consume an additional cooldown", sticky.Ready(110, false));
Check("A long attachment still starts a full cooldown on detachment", sticky.Detach(500) && !sticky.Attach(502.999, carrierB, false) && sticky.Attach(503, carrierB, false));
Check("Repeated grab observations do not extend detachment cooldown", sticky.Detach(504) && !sticky.Detach(506) && sticky.Attach(507, carrierA, false));
sticky.Stop();
Check("An exploded or disabled head cannot attach again", sticky.Carrier == null && !sticky.Attach(1000, carrierA, false));
sticky.NewLife();
Check("The next native throw clears the previous carrier and cooldown", sticky.Carrier == null && sticky.Attach(0, carrierA, false));
Check("Separate heads have independent transfer cooldowns", new CleanupStickyHeadClock<object>().Attach(0, carrierB, false));
Check("A missing target cannot consume a head attachment", !new CleanupStickyHeadClock<object>().Attach(0, null, false));

StalkingDollContactRules.Slide(1, 0, 1, 0, out double slideX, out double slideZ);
Check("Wall contact permits the stalker to move away", slideX == 1 && slideZ == 0);
StalkingDollContactRules.Slide(0, 1, 1, 0, out slideX, out slideZ);
Check("Wall contact permits motion parallel to the wall", slideX == 0 && slideZ == 1);
StalkingDollContactRules.Slide(-1, 0, 1, 0, out slideX, out slideZ);
Check("Head-on wall contact redirects rather than stopping forever", slideX == 0 && Math.Abs(slideZ) == 1);
StalkingDollContactRules.Slide(1, 0, -1, 0, out double otherX, out double otherZ);
Check("Opposing stalkers choose different passing sides", slideX == -otherX && slideZ == -otherZ);
StalkingDollContactRules.Slide(-1, 2, 1, 0, out slideX, out slideZ);
Check("Glancing wall contact keeps progress along the desired side", Math.Abs(slideX) < .000001 && slideZ > 0);
StalkingDollContactRules.Slide(0, 0, 1, 0, out slideX, out slideZ);
Check("Collision steering cannot move a stopped stalker", slideX == 0 && slideZ == 0);
bool contactInvariants = true;
for (int angle = 0; angle < 360; angle += 5)
    for (int heading = 0; heading < 360; heading += 5)
    {
        double nx = Math.Cos(angle * Math.PI / 180), nz = Math.Sin(angle * Math.PI / 180);
        double dx = 3 * Math.Cos(heading * Math.PI / 180), dz = 3 * Math.Sin(heading * Math.PI / 180);
        StalkingDollContactRules.Slide(dx, dz, nx, nz, out slideX, out slideZ);
        contactInvariants &= slideX * nx + slideZ * nz >= -.003001 &&
            Math.Abs(slideX * slideX + slideZ * slideZ - 9) < .000001;
    }
Check("Wall steering over all headings preserves speed without driving into the contact", contactInvariants);

Check("Headman Protection unlocks at four", !ProtectionRules.Eligible(3, false, 1) && ProtectionRules.Eligible(4, false, 1));
Check("Protection includes exactly twenty metres", ProtectionRules.Eligible(5, false, 400) && !ProtectionRules.Eligible(5, false, 400.001));
Check("Protection never replaces an existing target", !ProtectionRules.Eligible(5, true, 1));
Check("Protection rejects invalid distance", !ProtectionRules.Eligible(5, false, double.NaN) && !ProtectionRules.Eligible(5, false, -1));
var trudgeCall = new TrudgeCallCycle();
Check("Trudge Call unlocks at one", !TrudgeCallCycle.Unlocked(0) && TrudgeCallCycle.Unlocked(1));
Check("Trudge Call cannot queue below unlock", !trudgeCall.Strike(0));
Check("Every floor strike queues one pair regardless of damage", trudgeCall.Strike(1) && TrudgeCallCycle.Count == 2 && TrudgeCallCycle.Delay == 3);
Check("Repeated floor callbacks cannot queue a duplicate pair", !trudgeCall.Strike(5));
trudgeCall.Begin();
Check("The next swing can summon again", trudgeCall.Strike(5));
Check("Blind preserves vanilla difficulty zero", !BlindTargetClock.Unlocked(0));
Check("Stalker landing on terrain cannot damage itself", !StalkingDollRules.IncomingCollisionHurts(false, false, 20));
Check("Stalker falling onto a stationary valuable cannot damage itself", !StalkingDollRules.IncomingCollisionHurts(true, false, 0));
Check("Stalker pushing an object away cannot take self-impact damage", !StalkingDollRules.IncomingCollisionHurts(true, false, -5));
Check("Thrown objects moving into the stalker remain valid physical attacks", StalkingDollRules.IncomingCollisionHurts(true, false, 5));
Check("Passive player and monster body contacts cannot damage the stalker", !StalkingDollRules.IncomingCollisionHurts(true, true, 5));
Check("Slow contact and invalid speed cannot cause self-damage", !StalkingDollRules.IncomingCollisionHurts(true, false, .5) && !StalkingDollRules.IncomingCollisionHurts(true, false, double.NaN) && !StalkingDollRules.IncomingCollisionHurts(true, false, double.PositiveInfinity));
Check("Stalker can climb a small grounded threshold", StalkingDollStepRules.CanStep(.05, true, true, true));
Check("Stalker can climb above its previous 25cm limit", StalkingDollStepRules.CanStep(.4, true, true, true));
Check("Stalker includes the 50cm maximum step", StalkingDollStepRules.CanStep(.5, true, true, true));
Check("Stalker cannot climb above 50cm", !StalkingDollStepRules.CanStep(.501, true, true, true));
Check("Stalker does not step on flat or descending surfaces", !StalkingDollStepRules.CanStep(0, true, true, true) && !StalkingDollStepRules.CanStep(-.1, true, true, true));
Check("Stalker cannot step repeatedly while airborne", !StalkingDollStepRules.CanStep(.1, false, true, true));
Check("Stalker steps require body clearance and walkable ground", !StalkingDollStepRules.CanStep(.1, true, false, true) && !StalkingDollStepRules.CanStep(.1, true, true, false));
Check("Stalker step heights reject invalid numbers", !StalkingDollStepRules.CanStep(double.NaN, true, true, true) && !StalkingDollStepRules.CanStep(double.PositiveInfinity, true, true, true));
Check("Three steps each use their current support height", new[] { (0d, .2), (.2, .4), (.4, .6) }.All(step => StalkingDollStepRules.CanStep(step.Item2 - step.Item1, true, true, true)));
Check("Total staircase height does not expand the single-step limit", !StalkingDollStepRules.CanStep(.6, true, true, true));
Check("Stalker can step its centre a short distance past the riser", StalkingDollStepRules.CanAdvance(.2));
Check("Stalker step-in displacement is capped at half a metre", StalkingDollStepRules.CanAdvance(.5) && !StalkingDollStepRules.CanAdvance(.501));
Check("Stalker step-in rejects backwards or invalid displacement", !StalkingDollStepRules.CanAdvance(0) && !StalkingDollStepRules.CanAdvance(-.1) && !StalkingDollStepRules.CanAdvance(double.NaN) && !StalkingDollStepRules.CanAdvance(double.PositiveInfinity));
Check("Clown Staff unlocks at three and Shield at five", !DifficultyRules.ClownStaffUnlocked(2) && DifficultyRules.ClownStaffUnlocked(3) && !DifficultyRules.ClownShieldUnlocked(4) && DifficultyRules.ClownShieldUnlocked(5));
var clownReward = new ClownStaffLife();
Check("Clown Staff starts pinned", clownReward.Pinned);
Check("Clown death converts a surviving Staff exactly once", clownReward.Reward() && clownReward.Rewarded && !clownReward.Pinned && !clownReward.Reward());
Check("Laser expiry cannot remove rewarded Staff", !clownReward.Remove() && !clownReward.Removed);
var clownExpired = new ClownStaffLife();
Check("Laser expiry removes an unrewarded Staff once", clownExpired.Remove() && !clownExpired.Remove());
Check("Later Clown death cannot recreate an expired Staff", !clownExpired.Reward() && !clownExpired.Rewarded);
Check("Separate Staff rewards do not share lifecycle", new ClownStaffLife().Pinned);
Check("Loom Abduction stays locked until four", !AbductionClock.Eligible(3, 2, true, 25, 4) && AbductionClock.Eligible(4, 2, true, 25, 4));
Check("Loom Abduction shares living-player range and pursuit requirements", !AbductionClock.Eligible(5, 1, true, 1, 4) && !AbductionClock.Eligible(5, 2, false, 1, 4) && !AbductionClock.Eligible(5, 2, true, 25.001, 4));
for (int tier = 0; tier <= 5; tier++)
{
    var noDeathLoot = new BirthdayBalloonRewards<int>();
    for (int i = 0; i < 8; i++) noDeathLoot.Register(i);
    noDeathLoot.BeginDeath();
    Check($"Birthday death generates no rewards or summons at tier {tier}", Enumerable.Range(0, 8).All(i => noDeathLoot.Remove(i, BalloonPopCause.Damage, true, tier) == BalloonReward.None));
}
Check("Reaper Sprint unlocks at difficulty two", !ReaperSprintClock.Unlocked(0) && !ReaperSprintClock.Unlocked(1) && ReaperSprintClock.Unlocked(2) && ReaperSprintClock.Unlocked(5));
var sprint = new ReaperSprintClock();
Check("Reaper Sprint requires actual pursuit", !sprint.Begin(0, false, 100));
Check("Reaper Sprint does not trigger just below ten metres", !sprint.Begin(0, true, 99.999));
Check("Reaper Sprint rejects invalid distances", !sprint.Begin(0, true, double.NaN) && !sprint.Begin(0, true, -1));
Check("Reaper Sprint triggers exactly at ten metres", sprint.Begin(0, true, 100) && sprint.Mode == ReaperSprintMode.Preparing);
Check("Reaper Sprint cannot create a second body during preparation", !sprint.Begin(1, true, 400));
Check("Reaper remains visible until Headman birth is confirmed", sprint.Born() && sprint.Mode == ReaperSprintMode.Headman && !sprint.Born());
Check("Headman cannot recursively sprint even after its cooldown", !sprint.Begin(11, true, 400));
Check("Headman returns exactly at three metres", !sprint.ShouldReturn(true, 9.001) && sprint.ShouldReturn(true, 9));
Check("Headman returns if the inherited victim disappears", sprint.ShouldReturn(false, 400));
sprint.Restore();
Check("Return preparation cannot start another sprint", sprint.Mode == ReaperSprintMode.Restoring && !sprint.Begin(11, true, 400));
sprint.ReturnFailed();
Check("Failed return retains Headman instead of enabling a duplicate Reaper", sprint.Mode == ReaperSprintMode.Headman);
sprint.Restore();
sprint.Restored();
Check("Restoring Reaper does not reset its ten-second cooldown", !sprint.Begin(9.999, true, 100) && sprint.Begin(10, true, 100));
sprint.Cancel();
Check("Cancelled setup cannot thrash on every frame", !sprint.Begin(10.5, true, 100) && sprint.Begin(20, true, 100));
sprint.Die();
Check("Death prevents transformation and duplicate return", !sprint.Begin(100, true, 100) && !sprint.ShouldReturn(false, 0));
sprint.NewLife();
Check("A native new life restores Sprint eligibility", sprint.Begin(101, true, 100));
Check("Separate Reapers have independent sprint cooldowns", new ReaperSprintClock().Begin(0, true, 100));
Check("Blind unlocks at one and persists through five", Enumerable.Range(1, 5).All(BlindTargetClock.Unlocked));
var blind = new BlindTargetClock();
object blindA = new(), blindB = new();
Check("Blind does not fire without a target", !blind.TryCast(0, null));
Check("Blind waits three seconds after acquisition", !blind.TryCast(10, blindA) && !blind.TryCast(12.999, blindA));
Check("Blind first casts at exactly three seconds", blind.TryCast(13, blindA));
Check("Blind repeats every three seconds for the same target", !blind.TryCast(15.999, blindA) && blind.TryCast(16, blindA) && blind.TryCast(19, blindA));
Check("Blind target switch restarts the full interval", !blind.TryCast(21.9, blindB) && !blind.TryCast(24.899, blindB) && blind.TryCast(24.9, blindB));
Check("Blind target loss cancels pending time", !blind.TryCast(25, null) && !blind.TryCast(30, blindB) && !blind.TryCast(32.999, blindB) && blind.TryCast(33, blindB));
Check("Blind late frame emits once without a catch-up burst", blind.TryCast(100, blindB) && !blind.TryCast(100, blindB) && !blind.TryCast(102.999, blindB));
blind.Reset();
Check("Blind respawn resets even the same native target reference", !blind.TryCast(200, blindB) && !blind.TryCast(202.999, blindB) && blind.TryCast(203, blindB));
var secondBlind = new BlindTargetClock();
Check("Blind monsters have independent target timers", !secondBlind.TryCast(204, blindA) && blind.TryCast(206, blindB) && !secondBlind.TryCast(206, blindA) && secondBlind.TryCast(207, blindA));

Check("Monster wave never changes difficulty zero", !MonsterWaveClock.CanStart(0, true, true));
Check("Monster wave unlocks at one and persists at five", MonsterWaveClock.CanStart(1, true, true) && MonsterWaveClock.CanStart(5, true, true));
Check("Monster wave admission requires both a nearby living player and a blind spawn", !MonsterWaveClock.CanStart(1, false, true) && !MonsterWaveClock.CanStart(1, true, false));
Check("Active wave rejects destruction at its centre and twenty-metre boundary", MonsterWaveClock.SuppressTrigger(true, 0) && MonsterWaveClock.SuppressTrigger(true, 400));
Check("Outside twenty metres destruction can attempt replacement", !MonsterWaveClock.SuppressTrigger(true, 400.01f));
Check("Wave no longer suppresses triggers in the old twenty-to-thirty-metre annulus", !MonsterWaveClock.SuppressTrigger(true, 625));
Check("Wave spawns cannot be within or exactly three metres of any player", !WaveSpawnRules.PlayerDistanceAllowed(0) && !WaveSpawnRules.PlayerDistanceAllowed(8.999f) && !WaveSpawnRules.PlayerDistanceAllowed(9));
Check("Wave allows a blind spawn just beyond three metres", WaveSpawnRules.PlayerDistanceAllowed(9.001f));
Check("Inactive wave does not suppress local destruction", !MonsterWaveClock.SuppressTrigger(false, 0));
var retirement = new RpcRetirementClock();
Check("Network retirement is inactive until explicitly started", !retirement.Due(100));
retirement.Start(100);
Check("Network views remain registered for one second of draining", !retirement.Due(100) && !retirement.Due(100.999) && retirement.Due(101));
retirement.Start(100.5);
Check("Duplicate removal cannot restart the retirement grace", retirement.Due(101));
var lateGrabRetirement = new RpcRetirementClock();
lateGrabRetirement.Start(200);
lateGrabRetirement.Draining(200.9);
Check("A late grab gets a release grace before view removal", !lateGrabRetirement.Due(201) && lateGrabRetirement.Due(201.9));
lateGrabRetirement.Draining(202.8);
Check("Repeated late requests cannot keep removed objects alive indefinitely", !lateGrabRetirement.Due(202.999) && lateGrabRetirement.Due(203));
var earlyDrain = new RpcRetirementClock();
earlyDrain.Draining(500);
Check("A request cannot implicitly create retirement state", !earlyDrain.Due(1000));
var waveGate = new MonsterWaveTriggerGate();
Check("Wave first admission attempt is available immediately", waveGate.Ready(0) && waveGate.TryBeginCheck(0));
int extraWaveChecks = 0;
for (int destruction = 0; destruction < 19; destruction++) if (waveGate.TryBeginCheck(0)) extraWaveChecks++;
Check("Twenty simultaneous destructions run admission only once", extraWaveChecks == 0);
Check("Wave admission remains blocked before three seconds", !waveGate.Ready(2.999) && !waveGate.TryBeginCheck(2.999));
Check("Skipped destructions do not extend the three-second window", waveGate.Ready(3) && waveGate.TryBeginCheck(3));
Check("Each accepted check opens its own three-second window", !waveGate.TryBeginCheck(5.999) && waveGate.TryBeginCheck(6));
var failedWaveGate = new MonsterWaveTriggerGate();
Check("Failed admission also consumes the rate limit", failedWaveGate.TryBeginCheck(100) && !MonsterWaveClock.CanStart(1, true, false) && !failedWaveGate.TryBeginCheck(100.1));
Check("Failed admission can retry after three seconds", failedWaveGate.TryBeginCheck(103));
Check("Stage instances have independent admission windows", new MonsterWaveTriggerGate().TryBeginCheck(0));
var wave = new MonsterWaveClock();
Check("Inactive wave has no scheduled spawns or expiry", !wave.TakeGnome(1000) && !wave.Expired(1000));
wave.Start(100);
Check("Wave warning cannot spawn or decide before three seconds", !wave.Spawning && !wave.TakeGnome(102.999) && !wave.Decide(102.999, true));
Check("Wave checks posture at exactly three seconds", wave.AwaitingDecision(103) && wave.Decide(103, true) && wave.Spawning);
Check("Wave posture check runs only once", !wave.AwaitingDecision(103) && !wave.Decide(104, false) && wave.Spawning);
Check("Wave first Gnome pair waits one second after the warning", !wave.TakeGnome(103) && !wave.TakeGnome(103.999) && wave.TakeGnome(104));
Check("Wave cannot duplicate a scheduled pair", !wave.TakeGnome(104));
int waveGnomes = MonsterWaveClock.GnomesPerTick;
for (int second = 5; second < 20; second++) if (wave.TakeGnome(100 + second)) waveGnomes += MonsterWaveClock.GnomesPerTick;
Check("Wave requests exactly thirty-two Gnomes before its deadline", waveGnomes == 32);
Check("Wave stays active before twenty seconds", !wave.Expired(119.999));
Check("Wave expires at exactly twenty seconds", wave.Expired(120));
Check("Wave cannot spawn at or beyond its end", !wave.TakeGnome(120) && !wave.TakeGnome(121));
var extendedWave = new MonsterWaveClock();
extendedWave.Start(0);
extendedWave.Decide(3, true);
Check("Extended wave remains active at the old fifteen-second deadline", !extendedWave.Expired(15));
int extendedGnomes = 0;
