    Check("native explosion exposes its HurtCollider", game.GetType("ParticlePrefabExplosion").Fields.Any(f => f.Name == "HurtCollider" && f.FieldType.FullName == "HurtCollider"));
    Check("native HurtCollider supports exact enemy self-hit exclusion", game.GetType("HurtCollider").Fields.Any(f => f.Name == "enemyHost" && f.FieldType.FullName == "Enemy"));
    var enemyHurtInstructions = game.GetType("HurtCollider").Methods.Single(m => m.Name == "EnemyHurt").Body.Instructions;
    Check("native enemy wind-hit entry controls physical knockback", enemyHurtInstructions.Any(i => i.Operand is MethodReference m && m.Name == "PhysObjectHurt"));
    Check("native enemy wind-hit entry controls enemy stun", enemyHurtInstructions.Any(i => i.Operand is MethodReference m && m.DeclaringType.FullName == "EnemyStateStunned" && m.Name == "Set"));
    int ownerCheck = enemyHurtInstructions.ToList().FindIndex(i => i.Operand is FieldReference f && f.Name == "enemyHost");
    Check("native owner exclusion returns before damage and stun", ownerCheck >= 0 && enemyHurtInstructions.Skip(ownerCheck).Take(6).Any(i => i.OpCode.Code == Code.Ret) &&
        enemyHurtInstructions.Take(ownerCheck + 6).All(i => i.Operand is not MethodReference m || (m.Name != "Hurt" && m.Name != "Set")));
    foreach ((string type, string rpc) in new[] { ("ClownTrap", "TouchNoseRPC"), ("EnemyTricycle", "SetStateRPC"), ("PhysGrabObject", "GrabPlayerAddRPC") })
        Check($"Bella native RPC is master-only: {type}.{rpc}", game.GetType(type).Methods.Single(m => m.Name == rpc).Body.Instructions.Any(i => i.Operand is MethodReference m && m.Name == "MasterOnlyRPC"));
    Check("Bella bait grab request authenticates grabbing player", game.GetType("PhysGrabObject").Methods.Single(m => m.Name == "GrabStartedRPC").Body.Instructions.Any(i => i.Operand is MethodReference m && m.Name == "OwnerOnlyRPC"));
    foreach (string rpc in new[] { "UpdateStateRPC", "UpdatePlayerTargetRPC", "TransformSmallToBigRPC", "TransformBigToSmallRPC" })
        Check($"native Elsa RPC is master-only: {rpc}", game.GetType("EnemyElsa").Methods.Single(m => m.Name == rpc).Body.Instructions.Any(i => i.Operand is MethodReference m && m.Name == "MasterOnlyRPC"));
    Check("native Elsa growth uses a 4.1-second transformation", game.GetType("EnemyElsa").Methods.Single(m => m.Name == "StateTransformSmallToBig").Body.Instructions.Any(i => i.OpCode.Code == Code.Ldc_R4 && i.Operand is float f && Math.Abs(f - 4.1f) < .001f));
    Check("native Elsa despawn is completed by animation event", game.GetType("EnemyElsaAnim").Methods.Single(m => m.Name == "Despawn").Body.Instructions.Any(i => i.Operand is MethodReference m && m.DeclaringType.FullName == "EnemyParent" && m.Name == "Despawn"));
    foreach (string rpc in new[] { "UpdateStateRPC", "TargetPlayerRPC" })
        Check($"native Chef RPC is master-only: {rpc}", game.GetType("EnemyTumbler").Methods.Single(m => m.Name == rpc).Body.Instructions.Any(i => i.Operand is MethodReference m && m.Name == "MasterOnlyRPC"));
    Check("native drone candidate search uses the filtered rigidbody resolver", game.GetType("ItemDrone").Methods.Single(m => m.Name == "SphereCheck").Body.Instructions.Any(i => i.Operand is MethodReference m && m.Name == "GetHighestParentWithRigidbody"));
    Check("native drone attachment has a host-side entry before RPC emission", game.GetType("ItemDrone").Methods.Single(m => m.Name == "NewRayHitPoint").Body.Instructions.Any(i => i.Operand is MethodReference m && m.Name == "RPC"));
    Check("native drone can retract a rejected attachment", game.GetType("ItemDrone").Methods.Any(m => m.Name == "DeactivateMagnet" && m.Parameters.Count == 0));
    Check("native Gnome selection has exactly one valuable candidate lookup to filter", game.GetType("EnemyGnomeDirector").Methods.Single(m => m.Name == "StateAttackSet").Body.Instructions.Count(i => i.Operand is GenericInstanceMethod m && m.Name == "GetComponentInParent" && m.GenericArguments.SingleOrDefault()?.FullName == "ValuableObject") == 1);
    Check("native Gnome selection retains a player fallback", game.GetType("EnemyGnomeDirector").Methods.Single(m => m.Name == "StateAttackSet").Body.Instructions.Any(i => i.Operand is MethodReference m && m.Name == "UpdateState"));
    Check("native grab release broadcasts to vanilla grabbers", game.GetType("PhysGrabber").Methods.Single(m => m.Name == "OverrideGrabRelease").Body.Instructions.Any(i => i.OpCode.Code == Code.Ldstr && (string)i.Operand == "ReleaseObjectRPC"));
    Check("native release clears the grabbed object", game.GetType("PhysGrabber").Methods.Single(m => m.Name == "ReleaseObject").Body.Instructions.Any(i => i.Operand is FieldReference f && f.Name == "grabbedPhysGrabObject" && i.OpCode.Code == Code.Stfld));
    Check("native Chef tell leads to tumble", game.GetType("EnemyTumbler").Methods.Single(m => m.Name == "StateTell").Body.Instructions.Any(i => i.Operand is MethodReference m && m.Name == "UpdateState"));
    Check("native valuable value initializer remains a coroutine", game.GetType("ValuableObject").Methods.Single(m => m.Name == "DollarValueSet").ReturnType.FullName == "System.Collections.IEnumerator");
    Check("native Frog signed value adjustment is master-only", game.GetType("PhysGrabObjectImpactDetector").Methods.Single(m => m.Name == "HealRPC").Body.Instructions.Any(i => i.Operand is MethodReference m && m.Name == "MasterOnlyRPC"));
    Check("native Frog signed value adjustment preserves original value", game.GetType("PhysGrabObjectImpactDetector").Methods.Single(m => m.Name == "HealLogic").Body.Instructions.All(i => i.OpCode.Code != Code.Stfld || i.Operand is not FieldReference f || f.Name != "dollarValueOriginal"));
    Check("native Scream Doll state RPC is master-only", game.GetType("ScreamDollValuable").Methods.Single(m => m.Name == "SetStateRPC").Body.Instructions.Any(i => i.Operand is MethodReference m && m.Name == "MasterOnlyRPC"));
    Check("native Scream Doll animation uses the existing active bool", game.GetType("ScreamDollValuable").Methods.Single(m => m.Name == "StateActive").Body.Instructions.Any(i => i.OpCode.Code == Code.Ldstr && (string)i.Operand == "active"));
    Check("native Scream Doll host activity needs its random impulses suppressed", game.GetType("ScreamDollValuable").Methods.Single(m => m.Name == "StateActive").Body.Instructions.Any(i => i.Operand is MethodReference m && m.Name == "AddForce"));
    Check("native Scream Doll sound loop is available for host animation control", game.GetType("ScreamDollValuable").Fields.Any(f => f.Name == "loopPlaying" && f.FieldType.FullName == "System.Boolean"));
    Check("native Loom speed derives from prefab agent speed", game.GetType("EnemyNavMeshAgent").Methods.Single(m => m.Name == "Awake").Body.Instructions.Any(i => i.Operand is MethodReference m && m.Name == "get_speed"));
    Check("native physical object can suspend gravity and motion", game.GetType("PhysGrabObject").Methods.Any(m => m.Name == "OverrideKinematic") && game.GetType("PhysGrabObject").Methods.Any(m => m.Name == "OverrideZeroGravity"));
    Check("native remote camera orientation is serialized for observation", game.GetType("PlayerLocalCamera").Methods.Single(m => m.Name == "OnPhotonSerializeView").Body.Instructions.Any(i => i.Operand is MethodReference m && m.Name == "get_rotation"));
    Check("native hit validation is available for Stalking Doll monster damage cooldowns", game.GetType("HurtCollider").Methods.Single(m => m.Name == "CanHit").Parameters.Count == 5);
    Check("native valuable break entry exposes impact level without relying on dollar loss", game.GetType("PhysGrabObjectImpactDetector").Methods.Single(m => m.Name == "Break").Parameters.Any(p => p.Name == "breakLevel"));
    Check("native Bella reward size uses EnemyParent difficulty", game.GetType("EnemyParent").Fields.Any(f => f.Name == "difficulty" && f.FieldType.FullName.Contains("Difficulty")));
    Check("native valuable price is driven by component presence on the viewing client", game.GetType("PhysGrabber").Methods.Single(m => m.Name == "ShowValue").Body.Instructions.Any(i => i.Operand is GenericInstanceMethod m && m.Name == "GetComponent" && m.GenericArguments.SingleOrDefault()?.FullName == "ValuableObject"));
    Check("native extraction has an explicit valuable registration entry to exclude", game.GetType("ValuableObject").Methods.Any(m => m.Name == "AddToDollarHaulList"));
    foreach (string rpc in new[] { "SpawnBalloonRPC", "RemoveBalloonRPC", "PopAllBalloonsRPC" })
        Check($"native balloon RPC is master-only: {rpc}", game.GetType("EnemyBirthdayBoy").Methods.Single(m => m.Name == rpc).Body.Instructions.Any(i => i.Operand is MethodReference m && m.Name == "MasterOnlyRPC"));
}

Console.WriteLine($"All {passed} checks passed.");
}
catch (Exception exception)
{
    Console.Error.WriteLine(exception);
    return 1;
}
return 0;
